import React from 'react';
import { BrowserRouter as Router, Route, Routes, Link } from 'react-router-dom';
import ClienteManagement from './components/Clientes/ClienteManagement';
import CreateCliente from './components/Clientes/CreateCliente';
import ClienteList from './components/Clientes/ClienteList';
import ProjetoList from './components/Projetos/ProjetoList';
import CreateProjeto from './components/Projetos/CreateProjeto';
import AtividadeList from './components/Atividades/AtividadeList';
import CreateAtividade from './components/Atividades/CreateAtividade';

const App = () => {
  return (
    <Router>
      <div className="cliente-management">
        <h2>Gestão de Clientes</h2>

        {/* Links de Navegação */}
        <div className="navigation-links">
          <Link to="/clientes">Clientes</Link>
          <Link to="/projetos">Projetos</Link>
          <Link to="/atividades">Atividades</Link>
        </div>

        {/* Rotas do React Router */}
        <Routes>
          {/* Rota para a lista de Clientes */}
          <Route
            path="/clientes"
            element={<ClienteList />} // Aqui pode renderizar a lista de clientes
          />

          {/* Rota para criar um novo cliente */}
          <Route
            path="/clientes/criar"
            element={<CreateCliente />} // Página para criar um cliente
          />

          {/* Rota para ver os projetos de um cliente específico */}
          <Route
            path="/clientes/:clienteId/projetos"
            element={<ProjetoList />} // Exibe os projetos de um cliente
          />

          {/* Rota para criar um novo projeto para um cliente */}
          <Route
            path="/clientes/:clienteId/projetos/criar"
            element={<CreateProjeto />} // Página para criar projeto de um cliente
          />

          {/* Rota para ver as atividades de um projeto de um cliente */}
          <Route
            path="/clientes/:clienteId/projetos/:projetoId/atividades"
            element={<AtividadeList />} // Lista de atividades de um projeto
          />

          {/* Rota para criar uma nova atividade em um projeto de um cliente */}
          <Route
            path="/clientes/:clienteId/projetos/:projetoId/atividades/criar"
            element={<CreateAtividade />} // Página para criar nova atividade
          />

        </Routes>
      </div>
    </Router>
  );
};

export default App;
